/* Create a string object with EMBSTR encoding if it is smaller than
 * OBJ_ENCODING_EMBSTR_SIZE_LIMIT, otherwise the RAW encoding is
 * used.
 *
 * The current limit of 44 is chosen so that the biggest string object
 * we allocate as EMBSTR will still fit into the 64 byte arena of jemalloc. */
#define OBJ_ENCODING_EMBSTR_SIZE_LIMIT 44
robj *createStringObject(const char *ptr, size_t len) {
    if (len <= OBJ_ENCODING_EMBSTR_SIZE_LIMIT)
        return createEmbeddedStringObject(ptr,len);
    else
        return createRawStringObject(ptr,len);
}

/* Convert Lua stack values into a Redis argv array of string objects.
 * Reuses the Lua command argument cache when the cached SDS buffer is large
 * enough, otherwise creates a new string object. */
robj **luaArgsToRedisArgv(lua_State *lua, int *argc, int *argv_len) {
    int j;
    /* Require at least one argument */
    *argc = lua_gettop(lua);
    if (*argc == 0) {
        luaPushError(lua, "Please specify at least one argument for this redis lib call");
        return NULL;
    }

    /* Build the arguments vector (reuse a cached argv from last call) */
    if (lua_argv_size < *argc) {
        lua_argv = zrealloc(lua_argv,sizeof(robj*)* *argc);
        lua_argv_size = *argc;
    }
    *argv_len = lua_argv_size;

    for (j = 0; j < *argc; j++) {
        char *obj_s;
        size_t obj_len;
        char dbuf[64];

        if (lua_type(lua,j+1) == LUA_TNUMBER) {
            /* We can't use lua_tolstring() for number -> string conversion
             * since Lua uses a format specifier that loses precision. */
            lua_Number num = lua_tonumber(lua,j+1);
            obj_len = fpconv_dtoa((double)num, dbuf);
            dbuf[obj_len] = '\0';
            obj_s = dbuf;
        } else {
            obj_s = (char*)lua_tolstring(lua,j+1,&obj_len);
            if (obj_s == NULL) break; /* Not a string. */
        }
        /* Try to use a cached object. */
        if (j < LUA_CMD_OBJCACHE_SIZE && lua_args_cached_objects[j] &&
            lua_args_cached_objects_len[j] >= obj_len)
        {
            robj *cached = lua_args_cached_objects[j];
            if (cached->refcount == 1 &&
                (cached->encoding == OBJ_ENCODING_RAW ||
                 cached->encoding == OBJ_ENCODING_EMBSTR) &&
                cached->ptr != NULL)
            {
                sds s = cached->ptr;
                unsigned char flags = s[-1];
                size_t alloc = sdsalloc(s);
                if (alloc >= obj_len) {
                    lua_args_cached_objects[j] = NULL;
                    memcpy(s,obj_s,obj_len+1);
                    if ((flags & SDS_TYPE_MASK) == SDS_TYPE_5) {
                        unsigned char *fp = ((unsigned char*)s)-1;
                        *fp = SDS_TYPE_5 | (obj_len << SDS_TYPE_BITS);
                    } else {
                        sdssetlen(s, obj_len);
                    }
                    lua_argv[j] = cached;
                    continue;
                }
            }
        }
        lua_argv[j] = createStringObject(obj_s, obj_len);
    }

    /* Pop all arguments from the stack, we do not need them anymore
     * and this way we guaranty we will have room on the stack for the result. */
    lua_pop(lua, *argc);

    /* Check if one of the arguments passed by the Lua script
     * is not a string or an integer (lua_isstring() return true for
     * integers as well). */
    if (j != *argc) {
        freeLuaRedisArgv(lua_argv, j, lua_argv_size);
        luaPushError(lua, "Lua redis lib command arguments must be strings or integers");
        return NULL;
    }

    return lua_argv;
}

